(function(root){
'use strict';
const systems=[
['Ethics','Review effects, consent, fairness, evidence, and accountability.'],['Ethicalism','Maintain revisable ethical commitments.'],['Huwsters','Voluntary contributors to the fictional community.'],['Huwsterics','Inquiry into cooperation and disagreement.'],['Huwsterism','A voluntary tradition of care and shared responsibility.'],['Riceness','A provisional category for generosity and sufficiency.'],['Rice','A provisional resource and provisioning category.'],['Polite','Respectful address with room for firm disagreement.'],['Politness','Review courtesy and unresolved issues.'],['Liberalics','Examine liberty, autonomy, and pluralism.'],['Liberalism','Discuss diverse political traditions called liberalism.'],['Socialics','Examine cooperation and shared needs.'],['Socialism','Discuss diverse political traditions called socialism.'],['Account management','Track authorized account metadata locally.'],['Profile management','Edit local identity and participation notes.'],['Publication management','Track titles, user-recorded states, rights, and review.'],['Account ministry','Voluntary stewardship and handoffs.'],['Republication copyleft','Review actual licenses and redistribution requirements.'],['Management','Coordinate actions, owners, and review dates.'],['Ministry','A service role without implied public or religious authority.'],['Archangel afaustian','Reject coercive bargains and retain the ability to refuse.'],['Afaustian software','Keep purposes, limits, exits, and data handling visible.']];
function text(value,max=2000){if(typeof value!=='string'||value.length>max)throw Error('Invalid or oversized text field');return value.trim();}
function profile(fields){return {name:text(fields.name,200),bio:text(fields.bio),boundary:text(fields.boundary)};}
function account(fields){const service=text(fields.service,200),alias=text(fields.alias,200);if(!service||!alias)throw Error('Service and alias are required');return {service,alias,note:text(fields.note)};}
function publication(fields){const title=text(fields.title,500),status=fields.status;if(!title||!['draft','review','published','retired'].includes(status))throw Error('A title and supported status are required');const reference=text(fields.reference,1000);if(status==='published'&&!reference)throw Error('Published records need a reference; it is not automatically verified');return {title,status,reference,rights:text(fields.rights),review:text(fields.review)};}
function createStore(){return {profile:{name:'',bio:'',boundary:''},accounts:[],publications:[]};}
function add(store,kind,fields){if(!['accounts','publications'].includes(kind))throw Error('Unknown record type');if(store[kind].length>=100)throw Error('Session limit is 100 records per type');const item=kind==='accounts'?account(fields):publication(fields);store[kind].push(item);return item;}
function remove(store,kind,index){if(!['accounts','publications'].includes(kind)||!Number.isInteger(index)||index<0||index>=store[kind].length)throw Error('Invalid record index');store[kind].splice(index,1);}
function exportRecords(store){return JSON.stringify({format:'rasniki-archangel',version:1,notice:'Unencrypted local metadata; publication states and references are not verified.',profile:profile(store.profile),accounts:store.accounts.map(account),publications:store.publications.map(publication)},null,2);}
root.RasnikiArchangel={systems,profile,account,publication,createStore,add,remove,exportRecords};
})(globalThis);
